var o=219;var a=`219-refrigeration-and-food-shelf-life-management`;var r=`217`;var i={en:`Refrigeration and Food Shelf-Life Management`,ua:`Холодильне зберігання та керування термінами придатності`};var s={short:`Refrigeration slows microbial growth but does not sterilize food or give every product the same shelf life. Safe storage requires temperature checks, separate raw-food handling, date labels, and food-specific use limits.`,sections:[{title:`Core idea`,text:`Low temperature slows microbial metabolism; it does not kill every microorganism or erase contamination that happened earlier. Raw foods, leftovers, opened ingredients and ready-to-eat dishes need different handling and storage periods.`},{title:`Scientific / practical principles`,text:`Domestic refrigerators should stay at 4 °C (40 °F) or lower; freezing is commonly at −18 °C (0 °F) or lower. Refrigerator temperatures vary by shelf and door opening. Chilling a large hot pot too slowly can allow pathogens to multiply before the center gets cold.`},{title:`How to apply it`,text:`Use a refrigerator thermometer and suitable shallow containers; cool hot food using a safe, rapid method, protect and date-label food, and store raw meat below ready-to-eat products. Check official food-specific limits rather than applying one universal number to every cooked dish.`},{title:`Practical example`,text:`Design storage labels for fresh fish, a pot of cooked soup, washed salad leaves and opened yogurt. Decide which items must be eaten earliest, which need separate containers and what to do when a cold-chain breach is suspected.`},{title:`Common mistakes and limitations`,text:`An airtight package does not make fresh food shelf-stable. Smell or appearance cannot reliably detect all pathogens; freezing stops growth but does not undo toxin formation or previous mishandling.`},{title:`Additional application to this theory`,text:`The cold chain begins at receiving: use a refrigerator thermometer, cool prepared dishes promptly, mark preparation and opening dates, and use food-specific storage tables. Freezing generally halts microbial growth but does not repair earlier temperature abuse. Separate raw and ready-to-eat foods.`},{title:`Related theories`,text:`20, 25, 26, 27, 220, 280.`}]};var l={short:`Холодильне зберігання сповільнює ріст мікроорганізмів, але не стерилізує продукти й не встановлює однаковий термін придатності для всіх. Безпечність потребує контролю температури, розділення сирого й готового, маркування дат та правил для кожного продукту.`,sections:[{title:`Суть`,text:`Низька температура сповільнює обмін речовин мікроорганізмів, але не знищує їх усі та не усуває забруднення, яке сталося раніше. Сирі продукти, залишки страв, відкриті інгредієнти й готова їжа мають різні умови зберігання.`},{title:`Наукові та практичні принципи`,text:`У побутовому холодильнику підтримують 4 °C або нижче, а в морозильнику орієнтовно −18 °C або нижче. Температура змінюється залежно від полиці та частоти відкривання дверцят. Велика каструля гарячої їжі може охолоджуватися надто повільно, дозволяючи патогенам розмножуватися всередині.`},{title:`Як застосовувати`,text:`Користуйтеся термометром і неглибокими контейнерами, швидко й безпечно охолоджуйте готові страви, захищайте продукти від забруднення, підписуйте дати й зберігайте сире м’ясо нижче готових продуктів. Перевіряйте офіційні строки для конкретних груп їжі.`},{title:`Практичний приклад`,text:`Створіть маркування для свіжої риби, супу, помитого салату та відкритого йогурту. Визначте черговість використання, окреме пакування й дії за підозри порушення холодового ланцюга.`},{title:`Поширені помилки й обмеження`,text:`Герметична тара не робить швидкопсувний продукт придатним для зберігання без холодильника. Запах чи вигляд не виявляє всі патогени, а заморожування не усуває вже утворені токсини.`},{title:`Додаткове застосування до теми`,text:`Холодовий ланцюг починається з приймання продуктів: перевіряйте холодильник термометром, швидко охолоджуйте готову їжу, позначайте дати приготування й відкриття та користуйтеся таблицями для конкретних продуктів. Заморожування здебільшого зупиняє ріст мікробів, але не виправляє порушення температурного режиму раніше. Сире й готове зберігайте окремо.`},{title:`Пов’язані теорії`,text:`20, 25, 26, 27, 220, 280.`}]};var n=[220,280];var d=`References / Джерела`;var c=[`https://www.foodsafety.gov/food-safety-charts/cold-food-storage-charts`,`https://akaprod-www.foodsafety.gov/food-safety-charts/cold-food-storage-charts`,`https://www.fda.gov/food/consumers/tips-reduce-food-waste`];var f={id:219,slug:a,group:`217`,title:i,en:s,ua:l,related:n,referenceTitle:d,references:c};export{f as default,s as en,r as group,o as id,d as referenceTitle,c as references,n as related,a as slug,i as title,l as ua};